const commandReceipt=stage=>({stage,exitCode:0,signal:null,status:'COMMAND_SUCCEEDED',rawSha256:'a'.repeat(64)});
const completedFrontend=()=>{const files={'command-frontend-types.json':commandReceipt('frontend-types'),'command-frontend-lint.json':commandReceipt('frontend-lint'),'phase-frontend-failure.json':{phase:'frontend',status:'FAILED'}};for(let i=0;i<4;i++){const b=draft.execution.frontend.batches[i];files['command-frontend-tests-'+i+'.json']=commandReceipt('frontend-tests-'+i);files['frontend-tests-'+i+'-actual.json']={rawSha256:'a'.repeat(64),invocationSuccess:true,cases:[...b.expectedPassed.map(name=>({name,status:'passed'})),...b.expectedFiltered.map(name=>name.startsWith('C05 shared')?{unreviewedNameSha256:sha256(name),status:'skipped'}:{name,status:'skipped'})]};if(i<3)files['frontend-tests-'+i+'.json']={sourceHead:resume.checkout,reportSha256:'a'.repeat(64),wholeInvocationSucceeded:true,caseNames:b.expectedPassed}}return files};
test('fixed frontend resume revalidates ten real assertions and the corrected C05 hash without qualifying the failed job',()=>{const f=completedFrontend(),r=verifyCompletedFrontend(n=>f[n],draft);assert.equal(r.passed,10);assert.equal(r.filtered,8);assert.equal(r.originalJobQualified,false);assert.equal(r.originalJobConclusion,'failure');for(const mutate of [x=>x['command-frontend-types.json'].exitCode=2,x=>x['frontend-tests-3-actual.json'].cases.at(-1).unreviewedNameSha256='b'.repeat(64),x=>x['frontend-tests-0-actual.json'].cases[0].status='failed',x=>x['phase-frontend-failure.json'].status='PASSED']){const x=structuredClone(f);mutate(x);assert.throws(()=>verifyCompletedFrontend(n=>x[n],draft))}});
const completedAudit=()=>{const f={'audit.json':{status:'PASSED',threshold:'HIGH/CRITICAL',components:[{component:'frontend',status:'PASSED'},{component:'backend',status:'PASSED'}]}};for(const c of ['frontend','backend']){f['command-'+c+'-audit.json']=commandReceipt(c+'-audit');f[c+'-audit-summary.json']={stage:c+'-audit',exitCode:0,threshold:'HIGH/CRITICAL',format:'NPM_AUDIT_V2',errorCode:null,rawSha256:'a'.repeat(64),counts:{info:0,low:0,moderate:1,high:0,critical:0,total:1}}}return f};
test('fixed audit resume keeps moderate findings visible and rejects either failed or mismatched component',()=>{const f=completedAudit(),r=verifyCompletedAudit(n=>f[n]);assert.equal(r.frontend.counts.moderate,1);for(const mutate of [x=>x['command-backend-audit.json'].exitCode=1,x=>x['frontend-audit-summary.json'].counts.critical=1,x=>x['frontend-audit-summary.json'].rawSha256='b'.repeat(64),x=>x['audit.json'].components.pop()]){const x=structuredClone(f);mutate(x);assert.throws(()=>verifyCompletedAudit(n=>x[n]))}});
test('fixed SAST resume keeps original analysis settings and requires the real checkout and application paths',()=>{const current=readFileSync(new URL('../workflows/ci.yml',import.meta.url),'utf8'),small='paths: [.github/scripts/school-teacher-bindings.json, .github/scripts/school-teacher-checks.mjs, .github/scripts/school-teacher-scope.mjs, .github/scripts/school-teacher.test.mjs, server-version/e2e/school-teacher-browser.cjs, server-version/e2e/school-teacher-chrome-permissions.cjs, server-version/e2e/school-teacher-chrome-permissions.test.cjs, server-version/e2e/school-teacher-chrome.cjs, server-version/e2e/school-teacher-frontend-receipt.test.cjs, server-version/e2e/school-teacher-preflight-resume.test.cjs, server-version/e2e/school-teacher-ui.cjs]',full='paths: [server-version/backend/src, server-version/frontend/src, server-version/e2e, .github/scripts]',original=current.replace(small,full);assert.doesNotThrow(()=>verifySastConfig(original,current));assert.throws(()=>verifySastConfig(original,current.replace('ram: 3500','ram: 3000')));const log='\n2026-10-22T22:50:06.000Z '+resume.checkout+'\nlanguages: javascript-typescript\nconfig: '+full;assert.doesNotThrow(()=>verifySastLog(log));assert.throws(()=>verifySastLog(log.replace(resume.checkout,'a'.repeat(40))));assert.throws(()=>verifySastLog(log.replace(full,small)))});
test('completed frontend reuse preserves strict audit SAST and downstream artifact verification',()=>{const source=readFileSync(new URL('./school-teacher-checks.mjs',import.meta.url),'utf8'),body=source.slice(source.indexOf('async function frontend(b)'),source.indexOf('function databaseGuard'));assert(body.includes('await reuseCompletedFrontend(b)'));assert(!/batches\(|command\(/.test(body));assert(source.includes("else if(phase==='audit')await reuseOfficial('audit',b)"));const ci=readFileSync(new URL('../workflows/ci.yml',import.meta.url),'utf8');assert(ci.indexOf('school-teacher-checks.mjs sast-reuse')<ci.indexOf('      - name: initialize CodeQL'));assert(ci.includes('path: school-teacher-evidence/official-sast-reuse.json'));assert(ci.includes('git fetch --no-tags --depth=1 origin '+draft.base+' '+draft.productHead+' '));assert(!ci.includes('continue-on-error: true'))});
const built=draft.execution.officialFrontendBuild;
const fourthRun=()=>({...originalRun(),id:built.run,head_sha:built.head});
const fourthJob=()=>({...originalJob('frontend'),id:built.job,run_id:built.run,head_sha:built.head,conclusion:'success',completed_at:'2026-10-22T23:13:00Z',steps:[{name:'verify completed official frontend subchecks then run missing cases and compile once',status:'completed',conclusion:'success'}]});
test('completed frontend job must be the fixed successful producer despite its failed parent run',()=>{const now=Date.parse('2026-10-22T23:15:00Z');assert.doesNotThrow(()=>verifyCompletedFrontendJob(fourthRun(),fourthJob(),now));for(const mutate of [j=>j.conclusion='failure',j=>j.id++,j=>j.head_sha='0'.repeat(40),j=>j.steps=[]]){const j=fourthJob();mutate(j);assert.throws(()=>verifyCompletedFrontendJob(fourthRun(),j,now))}assert.throws(()=>verifyCompletedFrontendJob(fourthRun(),fourthJob(),now+86400000))});
const remainder=previous=>{const f={'frontend.json':{status:'PASSED',freshBuild:true,typesExecuted:false,typesAndLintOfficiallyReused:true,previousPassedCasesReused:10,currentCasesRequired:13},'official-frontend-reuse.json':{kind:'official-successful-subcheck-reuse',originalRun:resume.run,originalHead:resume.head,originalCheckout:resume.checkout,originalJob:resume.frontendJob,originalParentConclusion:'failure',originalJobConclusion:'failure',currentHead:built.checkout,inputs:{'server-version/frontend':built.frontendTree,'server-version/backend':built.backendTree},completed:previous}};for(const stage of ['frontend-build','frontend-manifest'])f['command-'+stage+'.json']=commandReceipt(stage);for(let i=4;i<9;i++){const batch=draft.execution.frontend.batches[i];f['command-frontend-tests-'+i+'.json']=commandReceipt('frontend-tests-'+i);f['frontend-tests-'+i+'-actual.json']={invocationSuccess:true,rawSha256:'a'.repeat(64),cases:[...batch.expectedPassed.map(name=>({name,status:'passed'})),...batch.expectedFiltered.map(name=>({name,status:'skipped'}))]};f['frontend-tests-'+i+'.json']={sourceHead:built.checkout,reportSha256:'a'.repeat(64),wholeInvocationSucceeded:true,caseNames:batch.expectedPassed}}return f};
test('completed frontend qualification rechecks all remaining thirteen and preserves the earlier failed identity',()=>{const previous=verifyCompletedFrontend(n=>completedFrontend()[n],draft),f=remainder(previous);assert.equal(verifyCompletedFrontendRemainder(n=>f[n],draft,previous).passed,23);for(const mutate of [x=>x['official-frontend-reuse.json'].originalJobConclusion='success',x=>x['command-frontend-build.json'].exitCode=1,x=>x['frontend-tests-8-actual.json'].cases[0].status='failed',x=>x['frontend-tests-7.json'].sourceHead='0'.repeat(40),x=>x['frontend-tests-4-actual.json'].invocationSuccess=false]){const x=structuredClone(f);mutate(x);assert.throws(()=>verifyCompletedFrontendRemainder(n=>x[n],draft,previous))}});
test('fixed frontend dist rejects traversal symlinks encryption and missing entrypoints before extraction',()=>{const entries=[{name:'index.html',mode:0o100644,encrypted:false},{name:'ci-build-manifest.json',mode:0o100644,encrypted:false}];assert.equal(validateDistEntries(entries),true);for(const bad of [{name:'../escape',mode:0,encrypted:false},{name:'/absolute',mode:0,encrypted:false},{name:'assets/link',mode:0o120777,encrypted:false},{name:'assets/file',mode:0,encrypted:true},entries[0]])assert.throws(()=>validateDistEntries([...entries,bad]));assert.throws(()=>validateDistEntries(entries.slice(0,1)))});
const buildFixture=()=>{const manifest={schemaVersion:1,sha:built.checkout,runId:String(built.run),kind:'frontend',lockDigest:'a'.repeat(64),contentDigest:'b'.repeat(64)},args={head:'c'.repeat(40),runId:'500',manifest,lockDigest:manifest.lockDigest,contentDigest:manifest.contentDigest,frontendTree:built.frontendTree},r={schemaVersion:1,status:'VERIFIED_OFFICIAL_FRONTEND_BUILD',currentHead:args.head,currentRun:args.runId,originalRun:built.run,originalHead:built.head,originalCheckout:built.checkout,originalJob:built.job,originalArtifact:built.buildArtifact,originalArtifactSha256:built.buildDigest,frontendTree:built.frontendTree,manifest};return {r,args}};
test('fixed frontend receipt verifies immutable original manifest and real current lock content and tree',()=>{const {r,args}=buildFixture();assert.doesNotThrow(()=>verifyFrontendBuildReceipt(r,args));for(const key of ['head','runId','lockDigest','contentDigest','frontendTree'])assert.throws(()=>verifyFrontendBuildReceipt(r,{...args,[key]:'0'.repeat(64)}));for(const key of ['originalRun','originalArtifact','originalArtifactSha256'])assert.throws(()=>verifyFrontendBuildReceipt({...r,[key]:'wrong'},args));assert.throws(()=>verifyFrontendBuildReceipt({...r,manifest:{...r.manifest,sha:args.head}},args))});
test('frontend scope accepts only fixed official dist reuse and keeps backend fresh without fallback',()=>{const {b,o,evidence}=fixture();assert.doesNotThrow(()=>validateCandidate(b,o,evidence));b.frontendBuildDecision='fresh-once';assert.throws(()=>validateCandidate(b,o,evidence))});
test('CJK preparation requires exact official package metadata and never treats failure as visual success',()=>{const metadata='Package: fonts-wqy-zenhei\nVersion: 0.9.45-8\nArchitecture: all\nFilename: pool/universe/f/fonts-wqy-zenhei/fonts-wqy-zenhei_0.9.45-8_all.deb\nSHA256: '+'a'.repeat(64)+'\n';assert.equal(verifyFontMetadata(metadata),'a'.repeat(64));for(const m of [metadata.replace('0.9.45-8','0.9.45-9'),metadata.replace('pool/universe','../bad'),metadata+'SHA256: '+'b'.repeat(64)+'\n',metadata.replace('a'.repeat(64),'bad')])assert.throws(()=>verifyFontMetadata(m));const source=readFileSync(new URL('./school-teacher-checks.mjs',import.meta.url),'utf8'),body=source.slice(source.indexOf('function prepareFonts()'),source.indexOf('function privateRoot()'));assert(body.includes("status:'BLOCKED'"));assert(body.includes('businessCollectionMayContinue:true'));assert(!/chmod|chown|sudo|sysctl|setuid/.test(body));assert(body.includes("status:'PREPARED_NOT_VISUALLY_QUALIFIED'"))});
test('independent backend migration and PG precede mandatory Chrome trust while font failure cannot qualify visuals',()=>{const w=readFileSync(new URL('../workflows/ci-school-teacher.yml',import.meta.url),'utf8'),chrome=w.indexOf('school-teacher-chrome.cjs preflight'),browser=w.indexOf('run: node server-version/e2e/school-teacher-browser.cjs');for(const phase of ['backend','migrate','postgres','verify-frontend-artifact','fonts'])assert(w.indexOf('school-teacher-checks.mjs '+phase)<chrome);assert(chrome>0&&browser>chrome);assert(w.includes('school-teacher-checks.mjs browser-report'));assert(!/continue-on-error/.test(w))});

test('SAST reuses unchanged applications but scans every exact changed control and browser source',()=>{const paths=[".github/scripts/school-teacher-bindings.json",".github/scripts/school-teacher-checks.mjs",".github/scripts/school-teacher-scope.mjs",".github/scripts/school-teacher.test.mjs","server-version/e2e/school-teacher-browser.cjs","server-version/e2e/school-teacher-chrome-permissions.cjs","server-version/e2e/school-teacher-chrome-permissions.test.cjs","server-version/e2e/school-teacher-chrome.cjs","server-version/e2e/school-teacher-frontend-receipt.test.cjs","server-version/e2e/school-teacher-preflight-resume.test.cjs","server-version/e2e/school-teacher-ui.cjs"];assert.equal(verifySastDelta((...a)=>{assert.deepEqual(a.slice(-2),['.github/scripts','server-version/e2e']);return paths.join('\n')}),true);for(const changed of [paths.slice(1),[...paths,'server-version/e2e/unknown.cjs'],paths.map(p=>p.endsWith('school-teacher-ui.cjs')?'server-version/frontend/src/changed.ts':p)])assert.throws(()=>verifySastDelta(()=>changed.join('\n')));assert.doesNotThrow(()=>verifyResumeInputs(draft,(...a)=>a[1]==='HEAD:server-version/e2e'?'b'.repeat(40):resumeRead(...a)))});

test('confirmed temporary Chrome permission preparation is a single guarded step after backend and before strict preflight',()=>{const w=readFileSync(new URL('../workflows/ci-school-teacher.yml',import.meta.url),'utf8'),name='      - name: apply the confirmed temporary runner Chrome write-permission tightening',start=w.indexOf(name),end=w.indexOf('      - name:',start+name.length),step=w.slice(start,end);assert(start>w.indexOf('school-teacher-checks.mjs postgres'));assert(start>w.indexOf('school-teacher-checks.mjs fonts'));assert(start>w.indexOf('name: school-teacher-backend-'));assert(end===w.indexOf('      - name: inspect this runner Chrome, no automatic install or fallback'));assert(step.includes("if: github.repository == 'caohuibj/eduK12-new-version' && github.event_name == 'pull_request' && github.event.pull_request.number == 338 && github.event.pull_request.head.ref == 'work/school-teacher-review-20261022' && github.event.pull_request.head.repo.full_name == github.repository"));assert(step.includes('SCHOOL_TEACHER_CHROME_TIGHTEN: confirmed-temporary-runner'));assert(step.includes('run: node server-version/e2e/school-teacher-chrome-permissions.cjs tighten'));assert.equal(w.split('SCHOOL_TEACHER_CHROME_TIGHTEN').length-1,1);assert(!/continue-on-error|sudo|chmod|chown|sysctl|no-sandbox/.test(step));assert(w.indexOf('school-teacher-chrome.cjs preflight')<w.indexOf('run: node server-version/e2e/school-teacher-browser.cjs'));const src=readFileSync(new URL('./school-teacher-checks.mjs',import.meta.url),'utf8');assert(src.includes("'server-version/e2e/school-teacher-chrome-permissions.cjs','server-version/e2e/school-teacher-ui.cjs'"))});
